#include <bits/stdc++.h>
using namespace std;
int main(){
    string line;
    int tc=1;
    while (getline(cin,line)) {
        if (line=="end") break;
        multiset<char> tops;
        for (char c : line) {
            auto it = tops.lower_bound(c);
            if (it != tops.end()) tops.erase(it);
            tops.insert(c);
        }
        printf("Case %d: %d\n", tc++, (int)tops.size());
    }
}

